// Generated by LCD Wizard - written fresh by every export.
//
// LVGL's failed checks come here (lv_conf.h, LV_ASSERT_HANDLER) - out of display
// memory above all - in place of LVGL's own while(1): a line on serial naming
// where, then a restart. Firmware never fails quietly. lv_conf.h names this
// function, so keep this file beside the sketch whenever you use that lv_conf.h.
#include <Arduino.h>
#include <esp_system.h>

extern "C" void lw_lvgl_fail(const char * file, int line)
{
    Serial.printf("LVGL failed a check at %s:%d (out of display memory?) - restarting\n", file, line);
    Serial.flush();
    delay(100);
    esp_restart();
}
